-- ArrivalByNationality
-- Based on the data from ForeignerArrivalNationality.xlsx
LOAD DATA LOCAL INFILE 'YearCountryArrival.csv'
INTO TABLE ArrivalByNationality
FIELDS TERMINATED BY ','
OPTIONALLY ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 LINES
(year, countryId, arrivalCount);

-- ArrivalByTransport
LOAD DATA LOCAL INFILE 'YearTransportArrival.csv'
INTO TABLE ArrivalByTransport
FIELDS TERMINATED BY ','
OPTIONALLY ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 LINES
(year, transportId, arrivalCount);

-- ProvincialTurnover
LOAD DATA LOCAL INFILE 'YearProvinceTurnover.csv'
INTO TABLE ProvincialTurnover
FIELDS TERMINATED BY ','
OPTIONALLY ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 LINES
(year, provinceId, turnoverAmount);

-- ExpenditureByCategory
LOAD DATA LOCAL INFILE 'YearCategoryTypeExpenditure.csv'
INTO TABLE ExpenditureByCategory
FIELDS TERMINATED BY ','
OPTIONALLY ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 LINES
(year, categoryId, typeId, expenditureAmount, currency);
